local EnterMood = "Enter%d"

local QuitMood = "Quit%d"

---@class UIBattlingBubbleNode
---@field ImgShadow                     	Engine.UI.RawImageAlterable
---@field TextContent                   	LetterTyperComp
---@field TextName                      	UnityEngine.UI.Text
---@field ImgHead                       	Engine.UI.RawImageAlterable
local UIBattlingBubbleNode = Class('UIBattlingBubbleNode')

---time * textLength
local BubbleTextTime = 0.05

function UIBattlingBubbleNode:__init()
    --
    self.cachedPath = nil
    self.currentMood = nil
    self.animator = nil
end

function UIBattlingBubbleNode:__delete()
    --
    self.cachedPath = nil
    self.currentMood = nil
    self.animator = nil
end

function UIBattlingBubbleNode:Awake()
    self.animator = self.controller.gameObject:GetComponent(typeof(CS.UnityEngine.Animator))
end

function UIBattlingBubbleNode:Start()
end

function UIBattlingBubbleNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

function UIBattlingBubbleNode:SetHeadIcon(path)
    if self.cachedPath == path then
        return
    end
    if string.isEmpty(path) then
        KTool.SetActive(self.ImgHead.gameObject, false)
        KTool.SetActive(self.ImgShadow.gameObject, false)
        return
    end
    self.cachedPath = path
    self.ImgHead:LoadSprite(path)
    self.ImgShadow:LoadSprite(path)
    KTool.SetActive(self.ImgHead.gameObject, true)
    KTool.SetActive(self.ImgShadow.gameObject, true)
end

function UIBattlingBubbleNode:SetMaskMood(moodId)
    --self.ImgMask.Status = moodId
    --if moodId == nil or moodId == 0 then
    --    moodId = 1
    --end
    self.currentMood = moodId
    self.animator:Play(string.format(EnterMood, moodId))
    
end

---@param vo BattleBubbleVo
function UIBattlingBubbleNode:StartBubble(vo)
    if string.isEmpty(vo.desc) then
        return
    end

    self.TextName.text = ""
    --self.TextContent.text = ""
    --local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(vo.skinId)
    --self.TextName.text = skinVo.name
    self.TextContent:SetText("")
    self.TextName.text = vo.skinName
    self:SetHeadIcon(vo.skinId)
    self:SetMaskMood(vo.moodId)
    --local length = string.len(vo.desc)
    --local time = length * BubbleTextTime
    --local tween = self.TextContent:DOText(vo.desc, time)
    --coroutine.yield(Yielders.GetWaitForSeconds(time))
    
    --if not tween:IsComplete() then
    --    tween:Complete()
    --end

    local txtContent = self.TextContent
    txtContent.AppearDuration = 0.2
    txtContent.PendingTime = 0.05
    txtContent.TextWillFill = vo.desc
    txtContent.IgnoreTimeScale = true
    coroutine.yield(txtContent:StartType())
end

function UIBattlingBubbleNode:CloseBubble()
    if not KTool.IsActiveInHierarchy(self.controller.gameObject) then
        return
    end
    
    cs_coroutine.start(function()
        self.animator:Play(string.format(QuitMood, self.currentMood))
        coroutine.yield(Yielders.GetWaitForSeconds(0.35))
        KTool.SetActive(self.controller.gameObject, false)
    end)
    
end

return UIBattlingBubbleNode

